-- Seed data for public.participants table in Supabase
INSERT INTO public.participants (name, type, role_or_category, email, phone, location, category, expertise_tags, image_url, description, description_el, description_ru, description_he, is_verified)
VALUES
  ('Electricity Authority of Cyprus (EAC / AHK)', 'Company', 'State Electricity Utility & Distribution System Operator', 'eacinfo@eac.com.cy', '+357 22 201000', 'Nicosia, Cyprus', 'Government & Associations', ARRAY['Smart Grids', 'Energy Efficiency', 'O&M', 'Policy & Regulatory']::TEXT[], '/logos/eac.svg', 'Cyprus state utility responsible for power generation, transmission, and distribution grid operation under DTR regulation.', 'Αρχή Ηλεκτρισμού Κύπρου: Ημικρατικός οργανισμός παραγωγής, μεταφοράς και διανομής ηλεκτρικής ενέργειας στην Κύπρο.', 'Государственная электрическая компания Кипра (EAC): генерация, передача и управление распределительными сетями электроснабжения.', 'רשות החשמל של קפריסין (EAC): הגוף הממשלתי האחראי ייצור, הולכה וחלוקת חשמל ברחבי קפריסין.', true),
  ('Cyprus Energy Regulatory Authority (CERA / RAEK)', 'Company', 'Independent Energy Market Regulator', 'info@cera.org.cy', '+357 22 666363', 'Nicosia, Cyprus', 'Government & Associations', ARRAY['Policy & Regulatory', 'PPA Structuring', 'Energy Trading']::TEXT[], '/logos/cera.svg', 'Independent regulatory authority monitoring the open electricity market, issuing generation licenses, and setting energy tariffs.', 'Ρυθμιστική Αρχή Ενέργειας Κύπρου (ΡΑΕΚ): Ανεξάρτητος ρυθμιστής αγοράς ηλεκτρισμού, αδειοδοτήσεων ΑΠΕ και τιμολογίων.', 'Регуляторный орган энергетики Кипра (CERA): лицензирование энергорынка, регулирование тарифов и контроль конкуренции.', 'רשות הרגולציה לאנרגיה של קפריסין (CERA): רגולטור עצמאי המפקח על שוק החשמל, מעניק רישיונות ומגדיר תעריפים.', true),
  ('Big Solar Cyprus Ltd', 'Company', 'MECI Registered PV Installer & Distributor', 'info@bigsolar.com.cy', '+357 22 870000', 'Nicosia, Cyprus', 'Renewables', ARRAY['Solar PV', 'EPC', 'Energy Efficiency', 'O&M']::TEXT[], '/logos/bigsolar.svg', 'Ministry-certified PV system installer and equipment distributor providing commercial net billing, energy efficiency upgrades, and solar power plants.', 'Πιστοποιημένος εγκαταστάτης φωτοβολταϊκών ΥΕΕΒΚ και διανομέας εξοπλισμού, παρέχοντας συστήματα net billing, ενεργειακές αναβαθμίσεις και φωτοβολταϊκά πάρκα.', 'Авторизованный MECI инсталлятор фотоэлектрических систем и дистрибьютор оборудования: коммерческий Net Billing, энергоаудит и солнечные станции.', 'מתקין מערכות סולאריות מורשה משרד האנרגיה ומפיץ ציוד, המספק מערכות נט-בילינג מסחריות, שדרוגי התייעלות אנרגטית ותחנות כוח סולאריות.', true),
  ('CGP Solar Systems Ltd', 'Company', 'MECI Certified PV & Battery Systems Contractor', 'info@cgpsolar.com', '+357 25 343434', 'Limassol, Cyprus', 'Renewables', ARRAY['Solar PV', 'Energy Storage', 'EPC', 'Energy Efficiency']::TEXT[], '/logos/cgpsolar.svg', 'MECI-registered renewable installer specializing in residential net-metering, commercial net-billing PV, and hybrid battery storage integration.', 'Εγγεγραμμένος εγκαταστάτης ΑΠΕ στο ΥΕΕΒΚ, με εξειδίκευση σε net-metering κατοικιών, εμπορικά φωτοβολταϊκά net-billing και ενσωμάτωση μπαταριών.', 'Сертифицированный MECI подрядчик по солнечной энергетике: домашние системы Net Metering, коммерческий Net Billing и накопители энергии.', 'קבלן מערכות סולאריות מוסמך MECI המתמחה בנט-מטרינג למגורים, נט-בילינג מסחρη ושילוב אגירת אנרגיה בסוללות.', true),
  ('First Electric Solar Ltd', 'Company', 'MECI Licensed Electrical & PV Engineering Contractor', 'contact@firstelectric.com.cy', '+357 24 636363', 'Larnaca, Cyprus', 'Engineering & EPC', ARRAY['Solar PV', 'EPC', 'Smart Grids', 'Energy Efficiency']::TEXT[], '/logos/firstelectric.svg', 'Licensed electrical engineering and solar installation contractor providing turnkey rooftop PV installations and industrial power upgrades.', 'Αδειούχος εργολήπτης ηλεκτρολογικών και φωτοβολταϊκών έργων, παρέχοντας ολοκληρωμένες εγκαταστάσεις στέγης και βιομηχανικές αναβαθμίσεις.', 'Лицензированный MECI электротехнический и солярный подрядчик: монтаж крышных СЭС под ключ и модернизация промышленных вводов.', 'קבלן הנדסת חשמל וסולאר מורשה, המספק התקנות סולאריות על גגות במתכונת עד המפתח ושדרוגי רשת תעשייתיים.', true),
  ('Cypra Bioenergy Ltd', 'Company', 'Biomass Waste-to-Energy & Biogas Generation Facility', 'info@cypra.com.cy', '+357 22 822800', 'Kato Moni, Nicosia, Cyprus', 'Renewables', ARRAY['ESG & Environmental', 'Energy Storage', 'Project Management', 'O&M']::TEXT[], '/logos/cypra.svg', 'Cyprus’s premier waste-to-energy biomass biogas plant converting livestock and agricultural waste into green grid electricity and organic fertilizer.', 'Η μεγαλύτερη μονάδα βιοαερίου και βιομάζας στην Κύπρο, που μετατρέπει γεωργοκτηνοτροφικά απόβλητα σε πράσινη ηλεκτρική ενέργεια.', 'Крупнейшая на Кипре биогазовая станция на биомассе: переработка сельскохозяйственных отходов в зеленую электроэнергию и органические удобрения.', 'מפעל הביומסה והביוגז המוביל בקפריסין להפקת אנרגיה מפסולת, הממיר פסולת חקלאית לחשמל ירוק ודשן אורגני.', true),
  ('Caramondani Energy Solutions (Caramondani Bros PLC)', 'Company', 'HV Substation & Power Grid EPC Engineering', 'info@caramondani.com.cy', '+357 22 816000', 'Nicosia, Cyprus', 'Engineering & EPC', ARRAY['Smart Grids', 'EPC', 'Energy Storage', 'Project Management']::TEXT[], '/logos/caramondani.svg', 'Pioneer engineering firm constructed high-voltage electrical substations, grid interconnections, and utility-scale power systems in Cyprus.', 'Πρωτοπόρος εταιρεία ηλεκτρολογικής μηχανικής, με κατασκευές υποσταθμών υψηλής τάσης, διασυνδέσεων δικτύου και ενεργειακών υποδομών.', 'Ведущая инжиниринговая компания: строительство высоковольтных подстанций, сетевых присоединений и объектов электроэнергетики.', 'חברת הנדסה מובילה העוסקת בהקמת תחנות משנה במתח גבוה, חיבורי רשת חשמל ומערכות כוח בקנה מידה ארצי.', true),
  ('Ergo Energy Contractors (Ergoleptiki Ltd)', 'Company', 'High-Voltage Grid & Transmission Line Engineers', 'info@ergo.com.cy', '+357 25 383838', 'Limassol, Cyprus', 'Engineering & EPC', ARRAY['Smart Grids', 'EPC', 'O&M', 'Project Management']::TEXT[], '/logos/ergo.svg', 'Specialized grid infrastructure contractor building medium and high voltage transmission lines, distribution networks, and transformer stations.', 'Εξειδικευμένος εργολήπτης υποδομών δικτύου, κατασκευάζοντας γραμμές μεταφοράς μέσης/υψηλής τάσης και μετασχηματιστές.', 'Подрядчик сетевой инфраструктуры: строительство ЛЭП среднего и высокого напряжения, распределительных сетей и трансформаторных станций.', 'קבלן תשתיות רשת מתמחה הבונה קווי הולכה במתח בינוני וגבוה, רשתות חלוקה ותחנות שנאים.', true),
  ('TPA Development & Grid Engineering (TPAD)', 'Company', 'Power Systems Engineering & Grid Stability Analysis', 'info@tpad.com.cy', '+357 22 313131', 'Nicosia, Cyprus', 'Engineering & EPC', ARRAY['Smart Grids', 'PPA Structuring', 'Project Management', 'Financial Advisory']::TEXT[], '/logos/tpad.svg', 'Power grid engineering and consultancy firm executing dynamic grid stability studies, TSOC compliance modeling, and renewable integration.', 'Εταιρεία σύμβουλων μηχανικών ηλεκτρικών συστημάτων, μελέτες ευσταθείας δικτύου, μοντελοποίηση TSOC και σύνδεση ΑΠΕ.', 'Инжиниринговая компания: моделирование устойчивости энергосистем, расчеты режимов для TSOC и интеграция возобновляемых источников.', 'חברת הנדסת מערכות כוח ומחקר המבצעת ניתוחי יציבות רשת דינמיים, מידול תאימות ל-TSOC ושילוב אנרגיה מתחדשת.', true)
